using Kerf.Engine.Exchange.Framework;
using Kerf.Engine.Foundation;
using System.Globalization;

namespace Kerf.Engine.Exchange.Step.Parser;

/// <summary>
/// The STEP parser (OCCT's <c>step::parser</c>, generated by bison from <c>step.yacc</c>, ISO 10303-21), written by
/// hand as a recursive descent: it reads the scanner's tokens and calls <see cref="ReadData"/> exactly as
/// the generated LALR(1) parser does, at the same tokens, including its error recovery and messages.
/// </summary>
/// <remarks>
/// <para>
/// The grammar (step.yacc; the rules' actions call StepFile_ReadData):
/// <code>
/// stepf   : STEP HEADER headl ENDSEC endhead model ENDSEC ENDSTEP      (stepf1)
///         | STEP HEADER ENDSEC endhead model ENDSEC ENDSTEP            (stepf2)
///         | STEP HEADER ENDSEC endhead model error  { return 0; }      (stepf3)
/// headl   : headent | headl headent
/// headent : enttype listarg ';' | error
/// endhead : DATA                                      { FinalOfHead }
/// unarg   : IDENT { SetTypeArg(Ident); CreateNewArg } | QUID { CreateNewArg }
///         | listarg { CreateNewArg } | listype listarg { CreateNewArg } | error { CreateErrorArg }
/// listype : TYPE { RecordTypeText }      deblist : '(' { RecordListStart }
/// finlist : ')' { RecordNewEntity; _yyerrstatus = 0 }
/// listarg : deblist finlist | deblist arglist finlist
/// arglist : unarg | arglist ',' unarg
/// model   : bloc | model bloc
/// bloc    : entlab '=' unent ';' | entlab '=' debscop model finscop unent ';'
///         | entlab '=' debscop finscop unent ';' | error
/// plex    : enttype listarg | plex enttype listarg
/// unent   : enttype listarg | '(' plex ')'
/// debscop : SCOPE { AddNewScope }        unid : IDENT { SetTypeArg(Ident); CreateNewArg }
/// export  : unid | export ',' unid       debexp : '/' { RecordListStart }
/// finscop : ENDSCOPE { FinalOfScope }
///         | ENDSCOPE debexp export '/' { RecordNewEntity; FinalOfScope }
/// entlab  : ENTITY { RecordIdent }       enttype : TYPE { RecordType }
/// </code>
/// </para>
/// <para>
/// Bison's parser reads a lookahead token only in the states that need one, and reduces (runs an action) before
/// reading when a state has a single reduction: the order of the scanner's actions (which set the current text and
/// argument type) and the parser's matters, and the methods below read tokens at the same points (the S numbers are
/// bison's states in step.tab.cxx). On a syntax error, bison reports it (unless fewer than three tokens were shifted
/// since the last one), pops its stack to the nearest state that shifts <c>error</c> (in a parameter list: the
/// list; in a scope: the scope's model; else the header's or the data's model) and discards tokens until one fits;
/// here the methods return false up to the method of that state, which recovers as bison does. A list's sub-lists
/// are read by a loop, not a recursion.
/// </para>
/// <para>
/// The parser adds the limits of <see cref="ParserReadLimits"/> and cancellation, which OCCT's hasn't.
/// </para>
/// </remarks>
internal sealed class StepParser
{
    /// <summary>The token kinds the scanner returns (bison's token::...; the characters are themselves).</summary>
    public static class Token
    {
        public const int YYEOF = 0;
        public const int STEP = 258;
        public const int HEADER = 259;
        public const int ENDSEC = 260;
        public const int DATA = 261;
        public const int ENDSTEP = 262;
        public const int SCOPE = 263;
        public const int ENDSCOPE = 264;
        public const int ENTITY = 265;
        public const int TYPE = 266;
        public const int IDENT = 269;
        public const int QUID = 276;
    }

    private const int Yyempty = -2;

    private readonly Scanner _scanner;
    private readonly ParserReadLimits _limits;
    private readonly ProgressRange _range;
    private ProgressScope _scope;
    private long _inputLength;
    private long _reported;
    private int _tokens;
    private int _depth;
    private int _yyerrstatus;
    private int _yyla = Yyempty;

    /// <summary>Raised to end the parse (YYABORT, or the return of stepf3's action).</summary>
    private sealed class Return(int theResult) : Exception
    {
        internal int Result { get; } = theResult;
    }

    /// <summary>A parser over <paramref name="scanner"/>'s tokens.</summary>
    public StepParser(Scanner scanner, ProgressRange range = default)
    {
        _scanner = scanner;
        _limits = scanner.Limits;
        _range = range;
    }

    private ReadData StepData => _scanner._dataModel;

    /// <summary>True when the parse stopped because the progress range was cancelled.</summary>
    public bool IsUserBreak { get; private set; }

    /// <summary>The limit that stopped the parse, or null.</summary>
    public string? ExceededLimit { get; private set; }

    /// <summary>
    /// Parses the input: 0 when it was accepted (possibly with errors recovered, in
    /// <see cref="ReadData.GetLastError"/>), 1 when the parser gave up (an error it couldn't recover, a limit
    /// reached, or cancellation).
    /// </summary>
    public int Parse()
    {
        _inputLength = _scanner.InputLength;
        _scope = new ProgressScope(_range, "Reading the STEP file", _inputLength > 0 ? _inputLength : 1);
        try
        {
            Stepf();
            return 0;
        }
        catch (Return aReturn)
        {
            return aReturn.Result;
        }
        catch (Scanner.FileTooLarge)
        {
            return Limit("file size", _limits.MaxFileSize);
        }
        finally
        {
            _scope.Close();
        }
    }

    // stepf : stepf1 | stepf2 | stepf3
    private void Stepf()
    {
        // S0
        if (Lookahead() != Token.STEP)
        {
            Error(Step);
            throw new Return(1);
        }

        Shift();
        // S1
        if (Lookahead() != Token.HEADER)
        {
            Error(Header);
            throw new Return(1);
        }

        Shift();
        bool isEmptyHead = Headl();
        Model(isEmptyHead);
    }

    /// <summary>
    /// The header (S6, S11: headl), then ENDSEC and endhead: true when the header has no entity (S6: stepf2 and
    /// stepf3), false when it has some (S11: stepf1). An error there (S6, S11, S13, S20, S9, S16) is recovered as
    /// <c>headent: error</c>.
    /// </summary>
    private bool Headl()
    {
        bool isEmpty = true;
        for (;;)
        {
            if (Headent(out bool isDone))
            {
                if (isDone)
                {
                    return isEmpty;
                }

                isEmpty = false;
                continue;
            }

            // headent : error (S8), headl (S11)
            isEmpty = false;
        }
    }

    private bool Headent(out bool isDone)
    {
        isDone = false;
        int tok = Lookahead();
        if (tok == Token.ENDSEC)
        {
            Shift();
            // S9, S16
            if (Lookahead() != Token.DATA)
            {
                return Error(Data);
            }

            Shift();
            // endhead : DATA
            StepData.FinalOfHead();
            isDone = true;
            return true;
        }

        if (tok == Token.TYPE)
        {
            Shift();
            Enttype();
            // S13
            if (Lookahead() != '(')
            {
                return Error(Paren);
            }

            Shift();
            Listarg();
            // S20
            if (Lookahead() != ';')
            {
                return Error(Semicolon);
            }

            Shift();
            return true;
        }

        return Error(EndseCorTYPE);
    }

    /// <summary>
    /// The data section (S15, S23 after an empty header; S26, S42 after a header with entities), then ENDSEC and
    /// ENDSTEP, then the end of the input. An error in a bloc is recovered as <c>bloc: error</c>, but after an empty
    /// header's first bloc (S23) the error shifts to S38, which ends the parse there (stepf3) at the end of the input.
    /// </summary>
    private void Model(bool isEmptyHead)
    {
        bool isEmpty = true;
        for (;;)
        {
            int tok = Lookahead();
            if (tok == Token.ENTITY)
            {
                Shift();
                if (Bloc())
                {
                    isEmpty = false;
                    continue;
                }
            }
            else if (tok == Token.ENDSEC && !isEmpty)
            {
                Shift();
                // S39, S52
                if (Lookahead() == Token.ENDSTEP)
                {
                    Shift();
                    // S46 (stepf2) or S61 (stepf1, which looks ahead for the ' ' bison's finvide expects); S5
                    if (Lookahead() == Token.YYEOF)
                    {
                        // S7: accepted
                        return;
                    }

                    Error(Eof);
                    throw new Return(1);
                }

                Error(Endstep);
            }
            else
            {
                Error(isEmpty ? Entity : EndseCorENTITY);
            }

            // The error token, shifted in S15, S26, S42 (S21: bloc : error) or S23 (S38)
            if (isEmptyHead && !isEmpty && Lookahead() == Token.YYEOF)
            {
                // stepf3 : STEP HEADER ENDSEC endhead model error  { return(0); }
                throw new Return(0);
            }

            isEmpty = false;
        }
    }

    /// <summary>A bloc after its label (S22: entlab is reduced); false on an error, for the model to recover.</summary>
    private bool Bloc()
    {
        // entlab : ENTITY
        StepData.RecordIdent();
        // S25
        if (Lookahead() != '=')
        {
            return Error(EqualsToken);
        }

        Shift();
        // S41
        int tok = Lookahead();
        if (tok == Token.SCOPE)
        {
            Shift();
            // debscop : SCOPE
            StepData.AddNewScope();
            Scope();
            return true;
        }

        if (tok != Token.TYPE && tok != '(')
        {
            return Error(ScopEorTYPEorParen);
        }

        return Unent() && Endbloc();
    }

    /// <summary>The ';' ending a bloc (S49, S69, S76).</summary>
    private bool Endbloc()
    {
        if (Lookahead() != ';')
        {
            return Error(Semicolon);
        }

        Shift();
        return true;
    }

    /// <summary>unent : enttype listarg | '(' plex ')', its first token being TYPE or '('.</summary>
    private bool Unent()
    {
        if (Lookahead() == Token.TYPE)
        {
            Shift();
            Enttype();
            // S51
            if (Lookahead() != '(')
            {
                return Error(Paren);
            }

            Shift();
            Listarg();
            return true;
        }

        Shift();
        // S48
        if (Lookahead() != Token.TYPE)
        {
            return Error(global::Kerf.Engine.Exchange.Step.Parser.StepParser.Type);
        }

        for (;;)
        {
            Shift();
            Enttype();
            // S55, S64
            if (Lookahead() != '(')
            {
                return Error(Paren);
            }

            Shift();
            Listarg();
            // S54
            int tok = Lookahead();
            if (tok == ')')
            {
                Shift();
                return true;
            }

            if (tok != Token.TYPE)
            {
                return Error(TypEorParenClose);
            }
        }
    }

    /// <summary>
    /// A scope after its debscop, to the end of its bloc (S50, S58: the scope's model; S57, S66, S67, S73 to S75,
    /// S79, S80: finscop; S59, S68: unent; S69, S76: ';'). Every error from the scope's start to the bloc's ';'
    /// returns here (S50 or S58 shifts error, as <c>bloc: error</c> of the scope's model), even after finscop.
    /// </summary>
    private void Scope()
    {
        Enter();
        for (;;)
        {
            if (ScopeStep())
            {
                _depth--;
                return;
            }

            // bloc : error (S21), model (S58)
        }
    }

    /// <summary>One bloc of the scope's model, or its end: true at the end of the scope's bloc.</summary>
    private bool ScopeStep()
    {
        int tok = Lookahead();
        if (tok == Token.ENTITY)
        {
            Shift();
            Bloc();
            return false;
        }

        if (tok != Token.ENDSCOPE)
        {
            Error(EndscopEorENTITY);
            return false;
        }

        Shift();
        // S57: finscop : ENDSCOPE (reduced after reading the next token) | ENDSCOPE debexp export '/'
        if (Lookahead() == '/')
        {
            Shift();
            // debexp : '/'
            StepData.RecordListStart();
            for (;;)
            {
                // S67, S79
                if (Lookahead() != Token.IDENT)
                {
                    Error(Ident);
                    return false;
                }

                Shift();
                // unid : IDENT
                StepData.SetTypeArg(ParamType.ParamIdent);
                StepData.CreateNewArg();
                // S75
                int next = Lookahead();
                if (next == '/')
                {
                    Shift();
                    // OCCT prints it with printf on the standard output (the port: the messenger's warnings)
                    global::Kerf.Engine.Foundation.Message.SendWarning("***  Warning : Export List not yet processed");
                    StepData.RecordNewEntity();
                    StepData.FinalOfScope();
                    break;
                }

                if (next != ',')
                {
                    Error(CommaOrSlash);
                    return false;
                }

                Shift();
            }
        }
        else
        {
            StepData.FinalOfScope();
        }

        // S59, S68
        tok = Lookahead();
        if (tok != Token.TYPE && tok != '(')
        {
            Error(TypEorParen);
            return false;
        }

        return Unent() && Endbloc();
    }

    // enttype : TYPE
    private void Enttype() => StepData.RecordType();

    /// <summary>
    /// A list after its '(' (deblist is reduced on it), to its ')' (finlist): S18, S19, S27 to S36, S43 to S45, S53.
    /// Sub-lists are read in the same loop. An error anywhere in a list is recovered in the innermost list, as an
    /// error argument (<c>unarg : error</c>), so it never leaves the list: the list ends at a ')' that fits, or the
    /// parse at the end of the input.
    /// </summary>
    private void Listarg()
    {
        // deblist : '('
        StepData.RecordListStart();
        Enter();
        int aBase = _depth;
        const int atStart = 0, afterComma = 1, afterArg = 2;
        int state = atStart;
        for (;;)
        {
            int tok = Lookahead();
            if (state != afterArg)
            {
                // S19 (after '('), S44 (after ',')
                if (tok == Token.TYPE)
                {
                    Shift();
                    // listype : TYPE
                    StepData.RecordTypeText();
                    // S33
                    if (Lookahead() != '(')
                    {
                        Error(Paren);
                        StepData.CreateErrorArg();
                        state = afterArg;
                        continue;
                    }

                    Shift();
                    StepData.RecordListStart();
                    Enter();
                    state = atStart;
                    continue;
                }

                if (tok == Token.IDENT)
                {
                    Shift();
                    // unarg : IDENT
                    StepData.SetTypeArg(ParamType.ParamIdent);
                    StepData.CreateNewArg();
                    state = afterArg;
                    continue;
                }

                if (tok == Token.QUID)
                {
                    Shift();
                    // unarg : QUID (deja fait par lex)
                    StepData.CreateNewArg();
                    state = afterArg;
                    continue;
                }

                if (tok == '(')
                {
                    Shift();
                    StepData.RecordListStart();
                    Enter();
                    state = atStart;
                    continue;
                }

                if (tok != ')' || state != atStart)
                {
                    // S19's five tokens are too many for bison's message, which then names none
                    Error(state == atStart ? null : TypEorIDENTorQUIDorParen);
                    // unarg : error
                    StepData.CreateErrorArg();
                    state = afterArg;
                    continue;
                }
            }
            else if (tok == ',')
            {
                // S36
                Shift();
                state = afterComma;
                continue;
            }
            else if (tok != ')')
            {
                Error(ParenCloseOrComma);
                StepData.CreateErrorArg();
                state = afterArg;
                continue;
            }

            Shift();
            // finlist : ')'
            if (StepData.GetModePrint() > 0)
            {
                StepData.PrintOutput.Write(string.Create(CultureInfo.InvariantCulture, $"Record no : {StepData.GetNbRecord() + 1} -- "));
                StepData.PrintCurrentRecord();
            }

            StepData.RecordNewEntity();
            _yyerrstatus = 0;
            _depth--;
            if (_depth < aBase)
            {
                return;
            }

            // unarg : listarg | listype listarg
            StepData.CreateNewArg();
            state = afterArg;
        }
    }

    /// <summary>The lookahead token, read if there is none.</summary>
    private int Lookahead()
    {
        if (_yyla == Yyempty)
        {
            if (StepData.GetNbRecord() > _limits.MaxRecords)
            {
                throw new Return(Limit("record count", _limits.MaxRecords));
            }

            if ((++_tokens & 4095) == 0)
            {
                Progress();
            }

            _yyla = _scanner.Lex();
        }

        return _yyla;
    }

    /// <summary>Shifts the lookahead token (bison counts the tokens shifted since an error).</summary>
    private void Shift()
    {
        if (_yyerrstatus != 0)
        {
            --_yyerrstatus;
        }

        _yyla = Yyempty;
    }

    /// <summary>One more level of lists or scopes.</summary>
    private void Enter()
    {
        if (++_depth > _limits.MaxDepth)
        {
            throw new Return(Limit("nesting depth", _limits.MaxDepth));
        }
    }

    /// <summary>
    /// A syntax error on the lookahead token where <paramref name="expected"/> fit (yyerrlab): reported unless
    /// fewer than three tokens were shifted since the last one; when none was, the token is discarded (and the parse
    /// ends at the end of the input). Returns false, for the caller to return up to the recovering method.
    /// </summary>
    private bool Error(string? expected)
    {
        if (_yyerrstatus == 0)
        {
            ErrorCore(expected is null
                ? "syntax error, unexpected " + TokenName(_yyla)
                : "syntax error, unexpected " + TokenName(_yyla) + ", expecting " + expected);
        }

        if (_yyerrstatus == 3)
        {
            // If just tried and failed to reuse lookahead token after an error, discard it
            if (_yyla == Token.YYEOF)
            {
                throw new Return(1);
            }

            _yyla = Yyempty;
        }

        _yyerrstatus = 3;
        return false;
    }

    // The tokens each state expects, as bison's verbose messages name them (the error token apart; none past four)
    private const string Step = "STEP";
    private const string Header = "HEADER";
    private const string Data = "DATA";
    private const string Endstep = "ENDSTEP";
    private const string Eof = "end of file";
    private const string Entity = "ENTITY";
    private const string Type = "TYPE";
    private const string Ident = "IDENT";
    private const string Paren = "'('";
    private const string Semicolon = "';'";
    private const string EqualsToken = "'='";
    private const string EndseCorTYPE = "ENDSEC or TYPE";
    private const string EndseCorENTITY = "ENDSEC or ENTITY";
    private const string EndscopEorENTITY = "ENDSCOPE or ENTITY";
    private const string ScopEorTYPEorParen = "SCOPE or TYPE or '('";
    private const string TypEorParen = "TYPE or '('";
    private const string TypEorParenClose = "TYPE or ')'";
    private const string TypEorIDENTorQUIDorParen = "TYPE or IDENT or QUID or '('";
    private const string ParenCloseOrComma = "')' or ','";
    private const string CommaOrSlash = "',' or '/'";

    /// <summary>The token's name in bison's messages (yytname_, quotes stripped as yytnamerr_ does).</summary>
    private static string TokenName(int theToken) => theToken switch
    {
        Token.YYEOF => "end of file",
        Token.STEP => "STEP",
        Token.HEADER => "HEADER",
        Token.ENDSEC => "ENDSEC",
        Token.DATA => "DATA",
        Token.ENDSTEP => "ENDSTEP",
        Token.SCOPE => "SCOPE",
        Token.ENDSCOPE => "ENDSCOPE",
        Token.ENTITY => "ENTITY",
        Token.TYPE => "TYPE",
        Token.IDENT => "IDENT",
        Token.QUID => "QUID",
        _ => "'" + (char)theToken + "'",
    };

    // step::parser::error
    private void ErrorCore(string m)
    {
        string newmess;
        bool isSyntax = m.StartsWith("syntax error", StringComparison.Ordinal);
        if (isSyntax && m.Length > 13)
        {
            newmess = string.Create(CultureInfo.InvariantCulture,
                $"Undefined Parsing: Line {_scanner.Lineno() + 1}: Incorrect syntax: {m[14..]}");
        }
        else if (isSyntax)
        {
            newmess = string.Create(CultureInfo.InvariantCulture, $"Undefined Parsing: Line {_scanner.Lineno() + 1}: Incorrect syntax");
        }
        else
        {
            newmess = string.Create(CultureInfo.InvariantCulture, $"Undefined Parsing: Line {_scanner.Lineno() + 1}: {m}");
        }

        StepFile_Interrupt(newmess, false);

        StepData.AddError(newmess);
    }

    /// <summary>StepFile_Read.cxx's trace of a parse error (unit 8B ports StepFile_Read, which may take it over).</summary>
    internal static void StepFile_Interrupt(string? errorMessage, bool isFail)
    {
        if (errorMessage == null)
        {
            return;
        }

        string text = "**** ERR StepFile : " + errorMessage + "    ****";
        if (isFail)
        {
            global::Kerf.Engine.Foundation.Message.SendFail(text);
        }
        else
        {
            global::Kerf.Engine.Foundation.Message.SendTrace(text);
        }
    }

    /// <summary>A limit reached: an error message, and the parse ends as an unrecoverable error does.</summary>
    private int Limit(string what, long limit)
    {
        ExceededLimit = what;
        StepData.AddError(string.Create(CultureInfo.InvariantCulture,
            $"Undefined Parsing: Line {_scanner.Lineno() + 1}: Limit reached: {what} above {limit}"));
        return 1;
    }

    /// <summary>Reports the bytes read, and stops the parse when the range is cancelled.</summary>
    private void Progress()
    {
        if (_scope.UserBreak())
        {
            IsUserBreak = true;
            StepData.AddError(string.Create(CultureInfo.InvariantCulture, $"Undefined Parsing: Line {_scanner.Lineno() + 1}: Reading cancelled"));
            throw new Return(1);
        }

        if (_inputLength > 0)
        {
            long read = Math.Min(_scanner.BytesRead, _inputLength);
            if (read > _reported)
            {
                ProgressRange step = _scope.Next(read - _reported);
                step.Close();
                _reported = read;
            }
        }
    }
}
